type ListSessionsParams struct {
	UserID          string
	IncludeArchived bool
}

func (q *Queries) ListSessions(ctx context.Context, arg ListSessionsParams) ([]Session, error) {
	rows, err := q.db.Query(ctx, listSessions, arg.UserID, arg.IncludeArchived)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Session{}
	for rows.Next() {
		var i Session
		if err := rows.Scan(
			&i.ID,
			&i.UserID,
			&i.ProjectID,
			&i.Title,
			&i.Description,
			&i.Prompt,
			&i.Status,
			&i.RepoURL,
			&i.BranchName,
			&i.BaseBranch,
			&i.Model,
			&i.CommitSha,
			&i.Summary,
			&i.Error,
			&i.Color,
			&i.Result,
			&i.CreatedAt,
			&i.StartedAt,
			&i.CompletedAt,
			&i.ArchivedAt,
			&i.AgentCancelOutcome,
			&i.AgentCancelAttempts,
			&i.AgentCancelNextAttemptAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

